</style></head><body><div class=toolbar><b>🏷️ Cetak Barcode Eksemplar</b><button onclick="window.print()">🖨️ Cetak Semua</button><a href=copies.php>← Kembali</a></div><div class=sheet><?php foreach($rows as $r):?><div class=label><div class=school>PERPUSTAKAAN SMPIT</div><div class=book><?=e($r['title'])?></div><svg class=barcode data-value="<?=e($r['code'])?>"></svg><div class=code><?=e($r['code'])?></div></div><?php endforeach?></div><script>document.querySelectorAll('.barcode').forEach(function(el){JsBarcode(el,el.dataset.value,{format:'CODE128',displayValue:false,width:1.4,height:48,margin:0});});</script></body></html>
